 "content": "def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(markers) < 2:
        return out

    # The marker surrounded by the colored pattern is the source; the isolated
    # marker is where that pattern is reproduced.
    def nearby_count(pos):
        r, c = pos
        return sum(
            1 for rr in range(max(0, r - 3), min(len(grid), r + 4))
            for cc in range(max(0, c - 3), min(len(grid[0]), c + 4))
            if (rr, cc) != pos and grid[rr][cc] != 0 and grid[rr][cc] != 5
        )

    source = max(markers, key=nearby_count)
    target = next((p for p in markers if p != source), markers[0])
    sr, sc = source
    tr, tc = target
    out[tr][tc] = 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0 and value != 5:
                rr, cc = tr + (r - sr), tc + (c - sc)
                if 0 <= rr < len(grid) and 0 <= cc < len(row):
                    out[rr][cc] = value
    return out
